(function () {
  var api = self.OpenTavernPlugin;
  if (!api) return;
  if (api.probe) { api.ready({ probe: true }); return; }
  var KEY = 'stats';
  var marker = api.resources.get('marker') || 'v2';
  var lastMessage = '';
  var refreshing = null;
  var refreshQueued = false;

  function summarize(stats) {
    var counts = { messages: 0, user: 0, assistant: 0, characters: 0 };
    (stats.messages || []).forEach(function (message) {
      counts.messages += 1;
      if (message.role === 'user') counts.user += 1;
      if (message.role === 'assistant') counts.assistant += 1;
      counts.characters += Number(message.characters) || 0;
    });
    return counts;
  }

  function renderFailure(error) {
    return api.ui.render({
      title: 'Conversation stats ' + marker,
      text: 'Stats failed: ' + (error && error.message || error),
      actions: [{ id: 'refresh', label: 'Retry' }]
    }).catch(function () {});
  }

  function refresh() {
    if (refreshing) {
      refreshQueued = true;
      return refreshing;
    }
    refreshing = api.stats.get().then(function (stats) {
      if (!stats || !stats.available) {
        return api.ui.render({
          title: 'Conversation stats ' + marker,
          text: 'No conversation is open.',
          actions: [{ id: 'refresh', label: 'Refresh' }]
        });
      }
      var counts = summarize(stats);
      lastMessage = stats.messages && stats.messages.length ? stats.messages[stats.messages.length - 1].role : 'none';
      var saved = {
        version: marker,
        conversation: stats.conversationId,
        messages: counts.messages,
        user: counts.user,
        assistant: counts.assistant,
        characters: counts.characters,
        last: lastMessage,
        updated: stats.updated
      };
      return api.storage.set(KEY, saved).then(function () {
        return api.ui.render({
          title: 'Conversation stats ' + marker,
          text: marker + ' · messages ' + counts.messages + ' · user ' + counts.user + ' · assistant ' + counts.assistant + ' · characters ' + counts.characters + ' · last ' + lastMessage,
          actions: [{ id: 'refresh', label: 'Refresh' }]
        });
      });
    }).catch(renderFailure).then(function () {
      refreshing = null;
      if (refreshQueued) {
        refreshQueued = false;
        refresh();
      }
    });
    return refreshing;
  }

  api.on('current-conversation-changed', refresh);
  api.on('conversation-saved', refresh);
  api.on('action', function (detail) {
    if (detail && detail.actionId === 'refresh') refresh();
  });
  api.ready();
  refresh();
})();
